<?php
require_once __DIR__ . '/includes/course_unlock.php';
header('Cache-Control: private, no-store');
$pdo=db();$who=current_user();$sid=$who && $who['role']===ROLE_STUDENT?(int)$who['id']:null;
$visible=bf_visible_course_ids($pdo,$sid);
$q=trim((string)($_GET['q']??''));$q=substr($q,0,100);
$level=(string)($_GET['level']??'');if(!in_array($level,['','beginner','intermediate','advanced'],true))$level='';
$rows=[];if($visible){$ids=implode(',',array_map('intval',$visible));
  $sql="SELECT c.id,c.title,c.description,c.category,c.thumbnail,c.level,u.full_name teacher_name,
         EXISTS(SELECT 1 FROM enrollments en WHERE en.course_id=c.id AND en.student_id=:sid AND en.status IN ('active','completed')) enrolled
         FROM courses c JOIN users u ON u.id=c.teacher_id WHERE c.id IN ($ids)";
  $params=['sid'=>$sid??0];if($q!==''){$sql.=' AND (c.title LIKE :q1 OR c.category LIKE :q2)';$params['q1']='%'.$q.'%';$params['q2']='%'.$q.'%';}
  if($level!==''){$sql.=' AND c.level=:level';$params['level']=$level;}
  $sql.=" ORDER BY FIELD(c.level,'beginner','intermediate','advanced'),c.created_at DESC";
  $st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll(PDO::FETCH_ASSOC);
}
function bf_thumb(?string $p):?string{return $p&&preg_match('~^uploads/courses/[a-zA-Z0-9_-]+\.(?:jpg|jpeg|png|webp)$~',$p)?app_url($p):null;}
$levels=['beginner'=>'Cơ bản','intermediate'=>'Trung bình','advanced'=>'Nâng cao'];
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Khám phá khóa học - BrightFuture</title><style>body{margin:0;background:#f4f6fd;color:#17223b;font-family:system-ui,-apple-system,"Segoe UI",sans-serif}*{box-sizing:border-box}.top{background:#fff;border-bottom:1px solid #e0e5ee;padding:17px 5%;display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap}.top a{color:#4f46e5;text-decoration:none;margin-right:15px;font-weight:600}.wrap{max-width:1140px;margin:32px auto;padding:0 18px}h1{font-size:29px;margin:0 0 12px}p{color:#64748b;line-height:1.6}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0}.toolbar input,.toolbar select,.form input,.form select{padding:11px;border:1px solid #d5dce9;border-radius:9px;background:#fff;max-width:100%}.toolbar input{flex:1;min-width:220px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:18px}.card{background:#fff;border:1px solid #e0e5ee;border-radius:15px;overflow:hidden}.image{width:100%;height:150px;object-fit:cover;background:#e0e7ff}.card-body{padding:20px}.card h2{font-size:19px;margin:8px 0}.tag{font-size:12px;color:#3730a3;background:#e7e8ff;border-radius:100px;padding:5px 10px}.button{display:inline-block;padding:10px 16px;border:0;background:#5046e5;color:#fff!important;border-radius:9px;text-decoration:none;font-weight:600;cursor:pointer}.button.secondary{background:#eef0ff;color:#3730a3!important}.notice{padding:15px;background:#fff7ed;border:1px solid #fed7aa;border-radius:10px;margin:15px 0}.success{background:#ecfdf5;border-color:#a7f3d0}.form{background:#fff;padding:22px;border:1px solid #e0e5ee;border-radius:14px;max-width:700px}.form label{display:block;margin:13px 0;font-weight:600}.form input,.form select{display:block;width:100%;margin-top:6px}.small{font-size:13px}.chapter{background:#fff;border:1px solid #e0e5ee;border-radius:12px;padding:18px;margin:12px 0}.lesson{padding:10px;border-top:1px solid #eef1f6}.lesson a{color:#4f46e5;text-decoration:none}@media(max-width:650px){.top{padding:13px}.wrap{margin:20px auto}h1{font-size:23px}}</style></head><body><header class="top"><strong>🎓 BrightFuture</strong><nav><a href="<?=e(app_url('dashboard.php'))?>">Tổng quan</a><a href="<?=e(app_url('student/my-courses.php'))?>">Khóa học của tôi</a><a href="<?=e(app_url('social.php'))?>">Cộng đồng</a><a href="<?=e(app_url('rooms.php'))?>">Phòng gọi</a><a href="<?=e(app_url('login.php'))?>">Đăng nhập</a></nav></header><main class="wrap"><h1>Khám phá khóa học</h1><p>Hoàn thành toàn bộ bài học và vượt qua bài kiểm tra cuối trình độ để mở khóa cấp tiếp theo.</p><form class="toolbar" method="get"><input name="q" placeholder="Tìm khóa học..." value="<?=e($q)?>"><select name="level"><option value="">Mọi trình độ đã mở</option><?php foreach($levels as $key=>$text):?><option value="<?=e($key)?>" <?=$level===$key?'selected':''?>><?=e($text)?></option><?php endforeach?></select><button class="button" type="submit">Tìm kiếm</button></form><div class="grid"><?php foreach($rows as $row):?><article class="card"><?php if($img=bf_thumb($row['thumbnail'])):?><img class="image" src="<?=e($img)?>" alt="Ảnh khóa học"><?php else:?><div class="image" style="display:grid;place-items:center;font-size:48px">▶</div><?php endif?><div class="card-body"><span class="tag"><?=e($levels[$row['level']]??$row['level'])?></span><h2><?=e($row['title'])?></h2><p class="small">Giáo viên: <?=e($row['teacher_name'])?></p><p><?=e(truncate_text((string)($row['description']??''),125))?></p><a class="button" href="<?=e(app_url('course.php?id='.(int)$row['id']))?>"><?=$row['enrolled']?'Tiếp tục học':'Xem và đăng ký'?></a></div></article><?php endforeach?></div><?php if(!$rows):?><div class="notice">Chưa có khóa học phù hợp hoặc bạn chưa mở khóa trình độ này. Nếu chưa đăng nhập, bạn chỉ thấy khóa Cơ bản.</div><?php endif?></main></body></html>
